<script setup>
import {ref,onMounted,onUnmounted} from 'vue';
const props=defineProps({eventId:Number,manage:Boolean,instructions:String});
let loadVersion=0;
const loading=ref(true),photos=ref({data:[]}),error=ref(''),busy=ref(false),consent=ref(false),file=ref(null),preview=ref(''),progress=ref(0),notice=ref('');
const base=()=> (props.manage?'/api/events/':'/api/student/events/')+props.eventId+'/photos';
function fail(e){error.value=Object.values(e.response?.data?.errors||{}).flat()[0]||e.response?.data?.message||e.message||'Não foi possível conectar.';}
async function load(page=1){const version=++loadVersion;loading.value=true;try{const {data}=await window.axios.get(base(),{params:{page}});if(version===loadVersion)photos.value=data;}catch(e){if(version===loadVersion)fail(e);}finally{if(version===loadVersion)loading.value=false;}}
async function choose(e){error.value='';file.value=null;const selected=e.target.files?.[0];e.target.value='';if(!selected)return;if(selected.size>20*1024*1024){error.value='Escolha uma foto de até 20 MB.';return;}busy.value=true;let url='';try{url=URL.createObjectURL(selected);const image=new Image();image.src=url;await image.decode();const ratio=Math.min(1,1920/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(image.naturalHeight*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.85));if(!blob)throw new Error();file.value=blob;if(preview.value)URL.revokeObjectURL(preview.value);preview.value=URL.createObjectURL(blob);}catch{error.value='Não foi possível abrir esta foto. Tente uma imagem JPG, PNG ou WebP.';}finally{if(url)URL.revokeObjectURL(url);busy.value=false;}}
async function upload(){if(!file.value||!consent.value)return;busy.value=true;error.value='';progress.value=0;try{const form=new FormData();form.append('photo',file.value,'foto.jpg');form.append('consent','1');await window.axios.post(base(),form,{onUploadProgress:e=>progress.value=e.total?Math.round(e.loaded/e.total*100):0});file.value=null;URL.revokeObjectURL(preview.value);preview.value='';notice.value='Foto enviada para aprovação da equipe.';await load();}catch(e){fail(e);}finally{busy.value=false;}}
async function moderate(photo,status){busy.value=true;error.value='';try{await window.axios.patch(base()+'/'+photo.id,{status});await load(photos.value.current_page);}catch(e){fail(e);}finally{busy.value=false;}}
onMounted(load);onUnmounted(()=>{if(preview.value)URL.revokeObjectURL(preview.value);});
</script>
<template><section class="student-card event-album"><h2>{{manage?'Moderar álbum':'Fotos do nosso encontro'}}</h2><p>{{instructions}}</p><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p>
<template v-if="!manage"><div class="album-upload-actions"><label class="btn-secondary">Escolher foto<input type="file" accept="image/*" :disabled="busy" @change="choose" /></label><label class="btn-secondary">Tirar foto<input type="file" accept="image/*" capture="environment" :disabled="busy" @change="choose" /></label></div><div v-if="file"><img class="album-preview" :src="preview" alt="Prévia da foto a enviar" /><label class="album-consent"><input type="checkbox" v-model="consent" />Autorizo compartilhar esta foto com os participantes do evento e confirmo ter autorização das pessoas retratadas.</label><button class="btn-primary" :disabled="busy||!consent" @click="upload">{{busy?'Enviando '+progress+'%':'Enviar para aprovação'}}</button></div></template>
<p v-if="loading" role="status">Carregando fotos…</p><p v-else-if="!photos.data.length">O álbum está começando. As fotos aprovadas aparecerão aqui.</p><div class="album-grid"><article v-for="photo in photos.data" :key="photo.id"><a v-if="photo.status!=='removed'" :href="photo.url" target="_blank" rel="noopener"><img :src="photo.thumbnailUrl" loading="lazy" alt="Foto compartilhada no evento" /></a><p>{{({pending:'Aguardando aprovação',approved:'Publicada',removed:'Removida do álbum'})[photo.status]}}</p><div v-if="manage"><button v-if="photo.status!=='approved'" class="btn-secondary" :disabled="busy" @click="moderate(photo,'approved')">Aprovar</button><button v-if="photo.status!=='removed'" class="btn-secondary" :disabled="busy" @click="moderate(photo,'removed')">Remover</button></div></article></div><div v-if="photos.last_page>1" class="album-pages"><button class="btn-secondary" :disabled="photos.current_page===1||busy" @click="load(photos.current_page-1)">Anterior</button><span>{{photos.current_page}} / {{photos.last_page}}</span><button class="btn-secondary" :disabled="photos.current_page===photos.last_page||busy" @click="load(photos.current_page+1)">Próxima</button></div></section></template>
<style scoped>.event-album{padding:24px!important;margin-top:20px}.event-album h2{font-size:24px;font-weight:750}.event-album p{margin:12px 0;line-height:1.6}.album-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:20px 0}.album-grid img{width:100%;aspect-ratio:1;object-fit:cover;border-radius:12px}.album-grid article{min-width:0}.album-grid button{min-height:44px;white-space:normal;margin:4px 4px 4px 0}.album-grid p{font-size:12px}.album-upload-actions,.album-pages{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:16px 0}.album-upload-actions label{cursor:pointer;position:relative;overflow:hidden}.album-upload-actions input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.album-preview{max-height:260px;max-width:100%;border-radius:12px}.album-consent{display:flex;align-items:start;gap:10px;font-size:13px;line-height:1.7;margin:16px 0}.album-consent input{flex-shrink:0;width:20px;height:20px;margin-top:3px}@media(max-width:400px){.event-album{padding:16px!important}.album-grid{gap:10px}}</style>
